import unittest

from frnadn.app import parse_java_properties


class TestJavaPropertiesImport(unittest.TestCase):
    def test_comments_whitespace_and_rooms(self):
        parsed = parse_java_properties(
            "# generated by FRN\n"
            "server_addr = frn.example.org\n"
            "server_port: 10024\n"
            "net00=Test\n"
            "net01 = World\n"
            "net01_tot=180\n"
            "! ignored\n"
        )
        self.assertEqual(parsed["server_addr"], "frn.example.org")
        self.assertEqual(parsed["server_port"], "10024")
        self.assertEqual(parsed["net01"], "World")
        self.assertEqual(parsed["net01_tot"], "180")

    def test_continuation(self):
        parsed = parse_java_properties("website=hello\\\n  world\n")
        self.assertEqual(parsed["website"], "helloworld")


if __name__ == "__main__":
    unittest.main()
